                return v
    return None
cy, cage, cgen, ca, ce = col('year'), col('age'), col('gender','sex'), col('actual'), col('expected')
print('mapped:', cy, cage, cgen, ca, ce)
if all([cy, ca, ce]):
    def agg(subset, keyf):
        d = collections.defaultdict(lambda: [0.0,0.0])
        for r in subset:
            k = keyf(r)
            d[k][0] += tof(r[ca]); d[k][1] += tof(r[ce])
        return {k: (a/e if e else None) for k,(a,e) in d.items()}
    inw = [r for r in rows if 2020 <= int(tof(r[cy])) <= 2022]
    outw = [r for r in rows if not (2020 <= int(tof(r[cy])) <= 2022)]
    keyf = (lambda r: (r.get(cgen,'?'), r.get(cage,'?'))) if (cgen and cage) else (lambda r: r.get(cgen or cage,'?'))
    ai = agg(inw, keyf); ao = agg(outw, keyf)
    print('--- segment: 2020-22 vs rest ---')
    for k in sorted(set(ai)|set(ao)):
        vi, vo = ai.get(k), ao.get(k)
        print(k, 'in:', None if vi is None else round(vi,3), 'out:', None if vo is None else round(vo,3))
    if cgen:
        g = collections.defaultdict(lambda: [0.0,0.0])
        for r in rows:
            y = int(tof(r[cy])); k = (y, r.get(cgen,'?'))
            g[k][0] += tof(r[ca]); g[k][1] += tof(r[ce])
        print('--- by gender by year ---')
        for y in sorted(set(k[0] for k in g)):
            print(y, {k[1]: round(g[(y,k[1])][0]/g[(y,k[1])][1],3) for k in g if k[0]==y and g[(y,k[1])][1]>0})

# --- IP termination monthly: scan large cells ---
print('--- IP termination by month ---')
with open('ae_ip_termination_by_month.csv') as f:
    rd = csv.DictReader(f)
    cols2 = rd.fieldnames
    rows2 = list(rd)
print('COLS2:', cols2, 'N:', len(rows2))
low2 = {c.lower(): c for c in cols2}
def col2(*subs):
    for s in subs:
        for k, v in low2.items():
            if s in k:
                return v
    return None
cd = col2('diag','condition','group','illness')
cm = col2('month','duration','month_in')
ca2 = col2('actual','recovered')
ce2 = col2('expected')
cae = col2('ae','a/e')
print('mapped2:', cd, cm, ca2, ce2, cae)
